// Example code snippet (Node.js + bpmn-js):
const BpmnJS = require('bpmn-js/lib/Modeler');
const fs = require('fs');

const modeler = new BpmnJS({ container: 'body' });
const diagramXML = fs.readFileSync('start.bpmn', 'utf8');

modeler.importXML(diagramXML, function(err) {
  if (err) {
    console.error('Import error:', err);
    return;
  }
  // Simulate user action: add a new task and connect with a sequence flow with a bend
  // (This part is typically done via UI, but can be scripted with modeler APIs)
  // ...
  // Export XML
  modeler.saveXML({ format: true }, function(err, xml) {
    if (err) {
      console.error('Export error:', err);
      return;
    }
    console.log(xml); // Look for the illegal waypoints property
  });
});
